"use client";

import React, { useState, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { UsersRound, CheckCircle2, AlertCircle, ArrowRight, Store, ShieldCheck } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

function AcceptInviteContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token") || "INV-SAMPLE-TOKEN-99218";
  const { register, login } = useAuth();

  const [staffName, setStaffName] = useState("");
  const [password, setPassword] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isJoined, setIsJoined] = useState(false);

  // Mock Org info from invitation token
  const inviteOrgName = "OmniPOS Kopi & Bakery";
  const assignedRole = "KASIR";

  const handleAccept = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const email = `${staffName.toLowerCase().replace(/\s+/g, "")}@omnipos.id`;
    await register(staffName, email, password, "KASIR");
    setIsJoined(true);

    setTimeout(() => {
      router.push("/pos");
    }, 1000);
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center p-4 bg-slate-50 dark:bg-zinc-950">
      <div className="w-full max-w-md bg-card border border-border rounded-2xl shadow-xl p-6 space-y-6">
        <div className="text-center space-y-2">
          <div className="w-12 h-12 rounded-2xl bg-primary/10 text-primary flex items-center justify-center font-bold text-xl mx-auto">
            <UsersRound className="w-6 h-6" />
          </div>
          <h1 className="text-xl font-extrabold text-foreground">Undangan Bergabung Tim</h1>
          <p className="text-xs text-muted-foreground">
            Anda diundang untuk bergabung ke workspace toko:
          </p>
          <div className="p-3 rounded-xl bg-muted/60 border border-border inline-block">
            <p className="font-bold text-sm text-foreground flex items-center justify-center gap-1.5">
              <Store className="w-4 h-4 text-primary" />
              <span>{inviteOrgName}</span>
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Peran yang Ditugaskan: <span className="font-semibold text-primary">{assignedRole}</span></p>
          </div>
        </div>

        {isJoined ? (
          <div className="p-6 text-center space-y-2 bg-green-50 dark:bg-green-950/30 rounded-xl border border-green-200 dark:border-green-800">
            <CheckCircle2 className="w-8 h-8 text-green-600 mx-auto animate-bounce" />
            <p className="font-bold text-sm text-green-800 dark:text-green-300">Berhasil Bergabung!</p>
            <p className="text-xs text-green-700 dark:text-green-400">Mengarahkan ke layar kasir POS...</p>
          </div>
        ) : (
          <form onSubmit={handleAccept} className="space-y-4">
            <div>
              <label className="text-xs font-semibold text-foreground">Nama Lengkap Staf</label>
              <Input
                placeholder="Contoh: Rian Kasir"
                value={staffName}
                onChange={(e) => setStaffName(e.target.value)}
                required
                className="mt-1 text-xs"
              />
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground">Buat Kata Sandi Akun</label>
              <Input
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="mt-1 text-xs"
              />
            </div>

            <div className="p-2.5 rounded-lg bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-900 text-[11px] text-blue-800 dark:text-blue-300 flex items-start gap-2">
              <ShieldCheck className="w-4 h-4 text-blue-600 shrink-0 mt-0.5" />
              <span>Akun Anda akan langsung terhubung ke toko pengundang tanpa membuat workspace ganda.</span>
            </div>

            <Button
              type="submit"
              disabled={isSubmitting}
              className="w-full font-bold text-xs h-10 shadow-md bg-green-600 hover:bg-green-700 text-white flex items-center justify-center gap-1.5"
            >
              <span>{isSubmitting ? "Menghubungkan..." : "Konfirmasi & Bergabung ke Toko"}</span>
              <ArrowRight className="w-4 h-4" />
            </Button>
          </form>
        )}
      </div>
    </div>
  );
}

export default function AcceptInvitePage() {
  return (
    <Suspense fallback={<div className="min-h-screen flex items-center justify-center text-xs">Memuat undangan...</div>}>
      <AcceptInviteContent />
    </Suspense>
  );
}

"use server";

import { db, ensureTablesExist, organizations, users, teamMembers, workspaceSettings, products, customers, transactions, cashierShifts, suppliers } from "@/db";
import { eq, desc, and } from "drizzle-orm";
import type { Product, Customer, Transaction, WorkspaceSettings, User, TeamMember, Supplier, CashierShift } from "@/db";

// Helper to check if Cloud DB is configured
export async function isCloudDbConnected(): Promise<boolean> {
  return !!db;
}

// ----------------------------------------------------
// 1. AUTH & WORKSPACE ONBOARDING (MULTI-TENANT)
// ----------------------------------------------------

export async function cloudRegister(
  name: string,
  email: string,
  passwordHash: string,
  role: string = "OWNER"
) {
  if (!db) return null;
  try {
    await ensureTablesExist();
    const normalizedEmail = email.toLowerCase().trim();

    // Check if user already exists
    const existing = await db.select().from(users).where(eq(users.email, normalizedEmail)).limit(1);
    if (existing.length > 0) {
      return { success: false, error: "Email ini sudah terdaftar. Silakan gunakan email lain atau masuk." };
    }

    const orgRandom = Math.random().toString(36).substring(2, 7);
    const orgId = `org-${Date.now()}-${orgRandom}`;
    const newOrgName = `Toko ${name.trim()}`;
    const userId = `usr-${Date.now()}-${orgRandom}`;

    // 1. Create organization
    await db.insert(organizations).values({
      id: orgId,
      name: newOrgName,
      businessType: "RETAIL",
      createdAt: new Date(),
      updatedAt: new Date(),
    });

    // 2. Create user
    const [newUser] = await db.insert(users).values({
      id: userId,
      name: name.trim(),
      email: normalizedEmail,
      password: passwordHash,
      createdAt: new Date(),
      updatedAt: new Date(),
    }).returning();

    // 3. Create team member link (Owner to this new org)
    await db.insert(teamMembers).values({
      id: `tm-${Date.now()}-${orgRandom}`,
      organizationId: orgId,
      userId: newUser.id,
      role: (role as any) || "OWNER",
      isActive: true,
      joinedAt: new Date(),
    });

    // 4. Create default workspace settings
    await db.insert(workspaceSettings).values({
      id: `set-${Date.now()}-${orgRandom}`,
      organizationId: orgId,
      businessName: newOrgName,
      currency: "IDR",
      taxEnabled: false,
      taxPercentage: "0.00",
      updatedAt: new Date(),
    });

    return {
      success: true,
      user: {
        id: newUser.id,
        name: newUser.name,
        email: newUser.email,
        role,
        organizationId: orgId,
        organizationName: newOrgName,
        businessType: "RETAIL",
        hasCompletedOnboarding: false,
      },
    };
  } catch (error: any) {
    console.error("cloudRegister error:", error);
    return { success: false, error: error.message || "Gagal registrasi ke cloud DB" };
  }
}

export async function cloudLogin(email: string, passwordHash: string) {
  if (!db) return null;
  try {
    await ensureTablesExist();
    const normalizedEmail = email.toLowerCase().trim();
    const userRecords = await db
      .select()
      .from(users)
      .where(and(eq(users.email, normalizedEmail), eq(users.password, passwordHash)))
      .limit(1);

    if (userRecords.length === 0) {
      return { success: false, error: "Email atau kata sandi tidak cocok." };
    }

    const matchedUser = userRecords[0];

    // Find user's active organization & role
    const members = await db
      .select()
      .from(teamMembers)
      .where(and(eq(teamMembers.userId, matchedUser.id), eq(teamMembers.isActive, true)))
      .limit(1);

    let orgId = `org-default-${matchedUser.id}`;
    let orgName = `Toko ${matchedUser.name}`;
    let role = "OWNER";
    let businessType = "RETAIL";

    if (members.length > 0) {
      role = members[0].role;
      orgId = members[0].organizationId;

      const orgs = await db.select().from(organizations).where(eq(organizations.id, orgId)).limit(1);
      if (orgs.length > 0) {
        orgName = orgs[0].name;
        businessType = orgs[0].businessType;
      }
    }

    return {
      success: true,
      user: {
        id: matchedUser.id,
        name: matchedUser.name,
        email: matchedUser.email,
        role,
        organizationId: orgId,
        organizationName: orgName,
        businessType,
        hasCompletedOnboarding: true,
      },
    };
  } catch (error: any) {
    console.error("cloudLogin error:", error);
    return { success: false, error: error.message };
  }
}

export async function cloudUpdateWorkspace(
  userId: string,
  organizationId: string,
  orgName: string,
  businessType: string
) {
  if (!db) return null;
  try {
    await ensureTablesExist();
    await db
      .update(organizations)
      .set({ name: orgName, businessType: businessType as any, updatedAt: new Date() })
      .where(eq(organizations.id, organizationId));

    await db
      .update(workspaceSettings)
      .set({ businessName: orgName, updatedAt: new Date() })
      .where(eq(workspaceSettings.organizationId, organizationId));

    return { success: true };
  } catch (error: any) {
    console.error("cloudUpdateWorkspace error:", error);
    return { success: false, error: error.message };
  }
}

