export async function cloudGetTeamMembers(organizationId: string) {
  if (!db) return null;
  try {
    await ensureTablesExist();
    const members = await db
      .select({
        id: users.id,
        name: users.name,
        email: users.email,
        phone: users.phone,
        role: teamMembers.role,
        isActive: teamMembers.isActive,
        joinedAt: teamMembers.joinedAt,
      })
      .from(teamMembers)
      .innerJoin(users, eq(teamMembers.userId, users.id))
      .where(eq(teamMembers.organizationId, organizationId));

    return members;
  } catch (error) {
    console.error("cloudGetTeamMembers error:", error);
    return null;
  }
}

export async function cloudCreateStaff(
  organizationId: string,
  name: string,
  email: string,
  passwordHash: string,
  role: string,
  phone?: string
) {
  if (!db) return null;
  try {
    await ensureTablesExist();
    const normalizedEmail = email.toLowerCase().trim();
    // Check if email already exists
    const existing = await db.select().from(users).where(eq(users.email, normalizedEmail)).limit(1);
    let userId = "";

    if (existing.length > 0) {
      userId = existing[0].id;
    } else {
      const [newUser] = await db.insert(users).values({
        id: `usr-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
        name: name.trim(),
        email: normalizedEmail,
        password: passwordHash,
        phone: phone || null,
        createdAt: new Date(),
        updatedAt: new Date(),
      }).returning();
      userId = newUser.id;
    }

    await db.insert(teamMembers).values({
      id: `tm-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      organizationId,
      userId,
      role: role as any,
      isActive: true,
      joinedAt: new Date(),
    });

    return { success: true };
  } catch (error: any) {
    return { success: false, error: error.message };
  }
}

