import { cloudGetSuppliers, cloudSaveSupplier, cloudDeleteSupplier } from "@/app/actions/cloud-sync";
import { HeaderKasir } from "@/components/HeaderKasir";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card } from "@/components/ui/atoms";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";

export default function SuppliersPage() {
  const router = useRouter();
  const { user, isLoading: authLoading } = useAuth();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [search, setSearch] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);

  const [name, setName] = useState("");
  const [contactPerson, setContactPerson] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [address, setAddress] = useState("");
  const [paymentTerms, setPaymentTerms] = useState("TOP 14 Hari");

  const orgId = user?.organizationId || "org-demo-1";
  const SUPPLIERS_STORAGE_KEY = `nstok_${orgId}_suppliers`;

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/login");
      return;
    }

    if (user) {
      const defaultSuppliers = INITIAL_SUPPLIERS.map((s) => ({ ...s, organizationId: orgId }));
      const local = loadFromLocalStorage<Supplier[]>(SUPPLIERS_STORAGE_KEY, defaultSuppliers);
      setSuppliers(local);

      cloudGetSuppliers(orgId).then((cloudData) => {
        if (cloudData && cloudData.length > 0) {
          setSuppliers(cloudData);
          saveToLocalStorage(SUPPLIERS_STORAGE_KEY, cloudData);
        } else if (local.length > 0) {
          for (const s of local) {
            cloudSaveSupplier(s).catch(() => {});
          }
        }
      }).catch(() => {});
    }
  }, [user, authLoading, orgId, router, SUPPLIERS_STORAGE_KEY]);

  const openAddModal = () => {
    setEditingSupplier(null);
    setName("");
    setContactPerson("");
    setPhone("");
    setEmail("");
    setAddress("");
    setPaymentTerms("Cash");
    setModalOpen(true);
  };

  const openEditModal = (s: Supplier) => {
    setEditingSupplier(s);
    setName(s.name);
    setContactPerson(s.contactPerson || "");
    setPhone(s.phone || "");
    setEmail(s.email || "");
    setAddress(s.address || "");
    setPaymentTerms(s.paymentTerms || "Cash");
    setModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;

    if (editingSupplier) {
      const updatedSup: Supplier = {
        ...editingSupplier,
        organizationId: orgId,
        name,
        contactPerson: contactPerson || null,
        phone: phone || null,
        email: email || null,
        address: address || null,
        paymentTerms: paymentTerms || "Cash",
      };
      const updated = suppliers.map((s) => (s.id === editingSupplier.id ? updatedSup : s));
      setSuppliers(updated);
      saveToLocalStorage(SUPPLIERS_STORAGE_KEY, updated);
      await cloudSaveSupplier(updatedSup);
    } else {
      const newSup: Supplier = {
        id: `sup-${Date.now()}`,
        organizationId: orgId,
        name,
        contactPerson: contactPerson || null,
        phone: phone || null,
        email: email || null,
        address: address || null,
        paymentTerms: paymentTerms || "Cash",
        createdAt: new Date(),
      };
      const updated = [newSup, ...suppliers];
      setSuppliers(updated);
      saveToLocalStorage(SUPPLIERS_STORAGE_KEY, updated);
      await cloudSaveSupplier(newSup);
    }
    setModalOpen(false);
  };

  const handleDelete = async (id: string) => {
    if (confirm("Hapus data supplier ini?")) {
      const updated = suppliers.filter((s) => s.id !== id);
      setSuppliers(updated);
      saveToLocalStorage(SUPPLIERS_STORAGE_KEY, updated);
      await cloudDeleteSupplier(id);
    }
  };

  const filtered = suppliers.filter((s) =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    (s.contactPerson && s.contactPerson.toLowerCase().includes(search.toLowerCase())) ||
    (s.phone && s.phone.includes(search))
  );

  return (
    <div className="flex-1 flex flex-col min-h-screen bg-background">
      <HeaderKasir />

      <div className="p-6 space-y-6 max-w-7xl mx-auto w-full">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <h1 className="text-xl font-extrabold text-foreground">Manajemen Pemasok & Vendor (Suppliers)</h1>
            <p className="text-xs text-muted-foreground">Pencatatan data vendor bahan baku dan termin pembayaran.</p>
          </div>
          <Button onClick={openAddModal} className="text-xs font-bold shrink-0">
            <Plus className="w-4 h-4 mr-1.5" />
            <span>Tambah Supplier Baru</span>
          </Button>
        </div>

        <div className="relative max-w-sm">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Cari nama supplier atau kontak..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 text-xs"
          />
        </div>

        <Card className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead className="bg-muted/40 text-muted-foreground border-b border-border">
                <tr>
                  <th className="py-3 px-4 font-semibold">Nama Perusahaan</th>
                  <th className="py-3 px-4 font-semibold">Contact Person</th>
                  <th className="py-3 px-4 font-semibold">Kontak (Telp / Email)</th>
                  <th className="py-3 px-4 font-semibold">Termin Pembayaran</th>
                  <th className="py-3 px-4 font-semibold text-right">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {filtered.map((sup) => (
                  <tr key={sup.id} className="hover:bg-muted/20 transition-colors">
                    <td className="py-3 px-4">
                      <p className="font-bold text-foreground">{sup.name}</p>
                      {sup.address && <p className="text-[10px] text-muted-foreground truncate max-w-xs">{sup.address}</p>}
                    </td>
                    <td className="py-3 px-4 text-muted-foreground">{sup.contactPerson || "-"}</td>
                    <td className="py-3 px-4 text-muted-foreground">
                      {sup.phone && <p className="font-mono">{sup.phone}</p>}
                      {sup.email && <p className="text-[10px]">{sup.email}</p>}
                    </td>
                    <td className="py-3 px-4 font-semibold text-primary">{sup.paymentTerms}</td>
                    <td className="py-3 px-4 text-right">
                      <div className="flex justify-end gap-1">
                        <button onClick={() => openEditModal(sup)} className="p-1.5 hover:bg-muted rounded text-primary">
                          <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => handleDelete(sup.id)} className="p-1.5 hover:bg-red-50 dark:hover:bg-red-950/30 rounded text-red-500">
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      </div>

      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingSupplier ? "Ubah Data Supplier" : "Tambah Supplier Baru"}</DialogTitle>
            <DialogDescription>Masukkan profil vendor pasokan barang / bahan baku.</DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSave} className="space-y-3">
            <div>
              <label className="text-xs font-semibold">Nama Perusahaan / Toko Supplier</label>
              <Input value={name} onChange={(e) => setName(e.target.value)} required className="mt-1 text-xs" />
            </div>
            <div>
              <label className="text-xs font-semibold">Contact Person (PIC)</label>
              <Input value={contactPerson} onChange={(e) => setContactPerson(e.target.value)} className="mt-1 text-xs" />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="text-xs font-semibold">Nomor Telepon</label>
                <Input value={phone} onChange={(e) => setPhone(e.target.value)} className="mt-1 text-xs" />
              </div>
              <div>
                <label className="text-xs font-semibold">Email</label>
                <Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="mt-1 text-xs" />
              </div>
            </div>
            <div>
              <label className="text-xs font-semibold">Alamat Gudang / Kantor</label>
              <Input value={address} onChange={(e) => setAddress(e.target.value)} className="mt-1 text-xs" />
            </div>
            <div>
              <label className="text-xs font-semibold">Termin Pembayaran</label>
              <Input value={paymentTerms} onChange={(e) => setPaymentTerms(e.target.value)} placeholder="Cash / TOP 14 Hari / TOP 30 Hari" className="mt-1 text-xs" />
            </div>
            <DialogFooter className="mt-4">
              <Button type="button" variant="outline" onClick={() => setModalOpen(false)}>Batal</Button>
              <Button type="submit" className="font-bold">Simpan Supplier</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth, Role, UserAccount } from "@/context/AuthContext";
import { HeaderKasir } from "@/components/HeaderKasir";
import { cloudGetTeamMembers } from "@/app/actions/cloud-sync";
import { 
  UsersRound, 
  Mail, 
  Plus, 
  ShieldAlert, 
  UserCheck, 
  UserX, 
  Trash2, 
  ShieldCheck, 
  Crown, 
  Key, 
  Users, 
  Phone, 
  AlertCircle, 
  CheckCircle2, 
  X, 
  ArrowLeft,
  Loader2,
  Info,
  Search
} from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, Badge } from "@/components/ui/atoms";

export default function TeamPage() {
  const router = useRouter();
  const { 
    user, 
    isLoading: authLoading, 
    getWorkspaceTeamMembers, 
    createStaffMember, 
    toggleStaffStatus, 
    deleteStaffMember 
  } = useAuth();

  const [members, setMembers] = useState<UserAccount[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedRole, setSelectedRole] = useState<string>("ALL");
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Form State
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [role, setRole] = useState<Role>("KASIR");
  const [formError, setFormError] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const refreshMembers = () => {
    const local = getWorkspaceTeamMembers();
    setMembers(local);

    if (user?.organizationId) {
      cloudGetTeamMembers(user.organizationId).then((cloudMembers) => {
        if (cloudMembers && cloudMembers.length > 0) {
          const mapped: UserAccount[] = cloudMembers.map((cm: any) => ({
            id: cm.id,
            name: cm.name,
            email: cm.email,
            role: cm.role as Role,
            organizationId: user.organizationId,
            organizationName: user.organizationName,
            businessType: user.businessType,
            hasCompletedOnboarding: true,
            createdAt: cm.joinedAt ? new Date(cm.joinedAt).toISOString() : new Date().toISOString(),
            isActive: cm.isActive,
            phone: cm.phone || "-",
          }));
          setMembers(mapped);
        }
      }).catch((e) => console.warn("Cloud team fetch warning:", e));
    }
  };

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/login");
      return;
    }
    if (user) {
      refreshMembers();
    }
  }, [user, authLoading, router]);

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  const handleAddStaff = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !email.trim() || !password) {
      setFormError("Nama, email, dan kata sandi wajib diisi.");
      return;
    }

    if (password.length < 6) {
      setFormError("Kata sandi minimal 6 karakter.");
      return;
    }

    setFormError(null);
    const res = await createStaffMember({
      name,
      email,
      password,
      role,
      phone,
    });

    if (res.success) {
      refreshMembers();
      setIsAddModalOpen(false);
      setName("");
      setEmail("");
      setPassword("");
      setPhone("");
      setRole("KASIR");
      showToast(`Staf "${name}" berhasil ditambahkan sebagai ${role}.`);
    } else {
      setFormError(res.error || "Gagal menambahkan staf.");
    }
  };

  const handleToggle = (member: UserAccount) => {
    toggleStaffStatus(member.id, !member.isActive);
    refreshMembers();
    showToast(`Status akun "${member.name}" diperbarui.`);
  };

  const handleDelete = (member: UserAccount) => {
    if (member.id === user?.id) {
      alert("Anda tidak dapat menghapus akun Anda sendiri.");
      return;
    }

    if (confirm(`Hapus akun staf "${member.name}" dari workspace toko ini?`)) {
      deleteStaffMember(member.id);
      refreshMembers();
      showToast(`Akun staf "${member.name}" berhasil dihapus.`);
    }
  };

  if (authLoading || !user) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-zinc-950 text-zinc-400">
        <Loader2 className="w-8 h-8 animate-spin text-emerald-500 mx-auto" />
      </div>
    );
  }

  const isOwnerOrManager = user.role === "OWNER" || user.role === "MANAGER";
  const isSupervisor = user.role === "SUPERVISOR";

  // If user is KASIR or STAFF, show Access Restricted
  if (!isOwnerOrManager && !isSupervisor) {
    return (
      <div className="flex flex-col h-screen w-screen overflow-hidden bg-background">
        <HeaderKasir />
        <main className="flex-1 flex items-center justify-center p-6">
          <div className="max-w-md w-full bg-card border border-border rounded-3xl p-8 text-center shadow-xl">
            <div className="w-16 h-16 rounded-2xl bg-amber-500/10 border border-amber-500/20 text-amber-500 flex items-center justify-center mx-auto mb-4">
              <ShieldAlert className="w-8 h-8" />
            </div>
            <h2 className="text-xl font-bold text-foreground mb-2">Akses Terbatas</h2>
            <p className="text-xs text-muted-foreground mb-6 leading-relaxed">
              Halaman <span className="text-foreground font-semibold">Pengaturan Tim</span> hanya dapat diakses oleh akun dengan peran <span className="text-amber-500 font-bold">Owner</span> atau <span className="text-purple-500 font-bold">Manager</span>.
            </p>
            <Button
              onClick={() => router.push("/pos")}
              className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              <span>Kembali ke Kasir POS</span>
            </Button>
          </div>
        </main>
      </div>
    );
  }

  const filteredMembers = members.filter((m) => {
    const matchSearch = m.name.toLowerCase().includes(searchTerm.toLowerCase()) || m.email.toLowerCase().includes(searchTerm.toLowerCase());
    const matchRole = selectedRole === "ALL" || m.role === selectedRole;
    return matchSearch && matchRole;
  });

  const getRoleBadge = (r: Role) => {
    switch (r) {
      case "OWNER":
        return <Badge className="bg-amber-500/10 text-amber-500 border-amber-500/20 font-bold"><Crown className="w-3 h-3 mr-1" /> Owner</Badge>;
      case "MANAGER":
        return <Badge className="bg-purple-500/10 text-purple-500 border-purple-500/20 font-bold"><Key className="w-3 h-3 mr-1" /> Manager</Badge>;
      case "SUPERVISOR":
        return <Badge className="bg-blue-500/10 text-blue-500 border-blue-500/20 font-bold"><ShieldCheck className="w-3 h-3 mr-1" /> Supervisor</Badge>;
      case "KASIR":
        return <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 font-bold"><Users className="w-3 h-3 mr-1" /> Kasir</Badge>;
      default:
        return <Badge variant="secondary">{r}</Badge>;
    }
  };

  return (
    <div className="flex flex-col h-screen w-screen overflow-hidden bg-background">
      <HeaderKasir />

      <main className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6">
        {/* Toast */}
        {toastMessage && (
          <div className="fixed top-6 right-6 z-50 bg-emerald-600 text-white px-4 py-2.5 rounded-xl shadow-xl flex items-center gap-2 text-xs font-bold animate-in fade-in slide-in-from-top-4">
            <CheckCircle2 className="w-4 h-4" />
            <span>{toastMessage}</span>
          </div>
        )}

        {/* Top Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-2 border-b border-border">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="px-2.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-500 text-xs font-bold border border-emerald-500/20">
                Toko: {user.organizationName}
              </span>
            </div>
            <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-foreground">
              Pengaturan Tim & Akun Kasir
            </h1>
            <p className="text-xs text-muted-foreground mt-0.5">
              Daftarkan staf kasir, supervisor, atau teknisi yang terhubung langsung dengan toko ini.
            </p>
          </div>

          <div className="flex items-center gap-2 self-start sm:self-auto">
            {isSupervisor && (
              <span className="px-3 py-1.5 rounded-lg bg-blue-500/10 text-blue-500 border border-blue-500/20 text-xs font-bold flex items-center gap-1.5">
                <Info className="w-3.5 h-3.5" />
                <span>Mode Lihat Saja</span>
              </span>
            )}
            {isOwnerOrManager && (
              <Button onClick={() => setIsAddModalOpen(true)} className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white cursor-pointer">
                <Plus className="w-4 h-4" />
                <span>Tambah Staf Baru</span>
              </Button>
            )}
          </div>
        </div>

        {/* Filters */}
        <div className="flex flex-col sm:flex-row items-center gap-3">
          <div className="relative flex-1 w-full">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Cari berdasarkan nama staf atau email..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 text-xs"
            />
          </div>

          <div className="flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto">
            {["ALL", "OWNER", "MANAGER", "SUPERVISOR", "KASIR"].map((r) => (
              <button
                key={r}
                onClick={() => setSelectedRole(r)}
                className={`px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap cursor-pointer transition-colors ${
                  selectedRole === r ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {r === "ALL" ? "Semua Peran" : r}
              </button>
            ))}
          </div>
        </div>

        {/* Team Table */}
        <Card className="overflow-hidden border-border bg-card">
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead className="bg-muted/40 border-b border-border text-muted-foreground uppercase font-semibold">
                <tr>
                  <th className="py-3 px-4">Nama Staf</th>
                  <th className="py-3 px-4">Peran</th>
                  <th className="py-3 px-4">Email Login</th>
                  <th className="py-3 px-4">Status</th>
                  <th className="py-3 px-4 text-right">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {filteredMembers.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="py-8 text-center text-muted-foreground">
                      Tidak ada anggota tim ditemukan.
                    </td>
                  </tr>
                ) : (
                  filteredMembers.map((m) => (
                    <tr key={m.id} className="hover:bg-muted/20 transition-colors">
                      <td className="py-3 px-4">
                        <div className="font-bold text-foreground text-sm flex items-center gap-2">
                          {m.name}
                          {m.id === user.id && (
                            <span className="text-[10px] bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-1.5 py-0.2 rounded">
                              Akun Anda
                            </span>
                          )}
                        </div>
                        {m.phone && m.phone !== "-" && (
                          <div className="text-[11px] text-muted-foreground flex items-center gap-1 mt-0.5">
                            <Phone className="w-3 h-3" />
                            <span>{m.phone}</span>
                          </div>
                        )}
                      </td>
                      <td className="py-3 px-4">{getRoleBadge(m.role)}</td>
                      <td className="py-3 px-4 font-mono text-foreground font-medium">{m.email}</td>
                      <td className="py-3 px-4">
                        {m.isActive ? (
                          <span className="inline-flex items-center gap-1 text-[11px] font-bold text-emerald-500">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                            Aktif
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-[11px] font-bold text-muted-foreground">
                            <span className="w-1.5 h-1.5 rounded-full bg-zinc-500" />
                            Non-Aktif
                          </span>
                        )}
                      </td>
                      <td className="py-3 px-4 text-right">
                        {isOwnerOrManager && (
                          <div className="flex items-center justify-end gap-1.5">
                            <button
                              onClick={() => handleToggle(m)}
                              className="p-1.5 rounded-lg border border-border text-muted-foreground hover:text-foreground hover:bg-muted cursor-pointer"
                              title={m.isActive ? "Nonaktifkan Akun" : "Aktifkan Akun"}
                            >
                              {m.isActive ? <UserX className="w-3.5 h-3.5" /> : <UserCheck className="w-3.5 h-3.5" />}
                            </button>
                            {m.id !== user.id && (
                              <button
                                onClick={() => handleDelete(m)}
                                className="p-1.5 rounded-lg border border-border text-muted-foreground hover:text-red-500 hover:bg-red-500/10 cursor-pointer"
                                title="Hapus Staf"
                              >
                                <Trash2 className="w-3.5 h-3.5" />
                              </button>
                            )}
                          </div>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>

        {/* Modal: Tambah Staf Baru */}
        <Dialog open={isAddModalOpen} onOpenChange={setIsAddModalOpen}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>Tambah Staf Toko Baru</DialogTitle>
              <DialogDescription>
                Staf yang dibuat akan otomatis terdaftar pada workspace {user.organizationName}.
              </DialogDescription>
            </DialogHeader>

            {formError && (
              <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-xs flex items-center gap-2">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{formError}</span>
              </div>
            )}

            <form onSubmit={handleAddStaff} className="space-y-3.5 py-2">
              <div>
                <label className="text-xs font-semibold text-foreground">Nama Lengkap Staf</label>
                <Input
                  placeholder="Contoh: Rina Kasir"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                  className="mt-1"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Alamat Email Login</label>
                <Input
                  type="email"
                  placeholder="kasir@email.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  className="mt-1"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Kata Sandi Awal (Min. 6 Karakter)</label>
                <Input
                  type="password"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="mt-1"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">Peran Pengguna</label>
                <select
                  value={role}
                  onChange={(e) => setRole(e.target.value as Role)}
                  className="w-full mt-1 px-3 py-2 text-xs rounded-md border border-input bg-background"
                >
                  <option value="KASIR">Kasir (Transaksi POS, Shift Kasir, Cetak Struk)</option>
                  <option value="SUPERVISOR">Supervisor (Otorisasi Void, Approval Diskon)</option>
                  <option value="MANAGER">Manager (Kelola Produk, Laporan, & Staf)</option>
                  <option value="STAFF_DAPUR">Staff Dapur (Kitchen Display KDS)</option>
                  <option value="TEKNISI">Teknisi (Work Order Bengkel)</option>
                </select>
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground">No. Telepon / WhatsApp (Opsional)</label>
                <Input
                  placeholder="0812-xxxx-xxxx"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  className="mt-1"
                />
              </div>

              <DialogFooter className="pt-3">
                <Button type="button" variant="outline" onClick={() => setIsAddModalOpen(false)}>
                  Batal
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white">
                  Simpan Staf
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </main>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { 
  Trash2, 
  Plus, 
  Minus, 
  User, 
  Bookmark, 
  CreditCard, 
  Percent, 
  Tag, 
  Utensils, 
  FileText,
  AlertCircle
} from "lucide-react";
import { useCart } from "@/context/CartContext";
import { useWorkspaceSettings } from "@/context/WorkspaceSettingsContext";
import { useBusinessMode } from "@/context/BusinessModeContext";
import { Customer } from "@/db/schema";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";

export function CartSidebar({
  onCheckout,
  onOpenApprovalModal,
  customersList = [],
  className = ""
}: {
  onCheckout: () => void;
  onOpenApprovalModal: (discountVal: number) => void;
  customersList?: Customer[];
  className?: string;
}) {
  const { 
    items, 
    updateQuantity, 
    removeFromCart, 
    clearCart,
    subtotal,
    taxAmount,
    grandTotal,
    discountPercent,
    discountAmount,
    setDiscountPercent,
    setDiscountAmount,
    selectedCustomer,
    setSelectedCustomer,
    tableNumber,
    setTableNumber,
    orderNotes,
    setOrderNotes,
    holdBills,
    holdCurrentBill,
    restoreHoldBill,
    deleteHoldBill
  } = useCart();

  const { formatCurrency, settings } = useWorkspaceSettings();
  const { mode } = useBusinessMode();

  const [customerModalOpen, setCustomerModalOpen] = useState(false);
  const [holdModalOpen, setHoldModalOpen] = useState(false);
  const [discountModalOpen, setDiscountModalOpen] = useState(false);
  const [inputDiscount, setInputDiscount] = useState("");

  const handleApplyDiscount = () => {
    const val = parseFloat(inputDiscount) || 0;
    if (val > settings.approvalDiscountThresholdPercent) {
      // Trigger supervisor approval modal
      setDiscountModalOpen(false);
      onOpenApprovalModal(val);
    } else {
      setDiscountPercent(val);
      setDiscountAmount(0);
      setDiscountModalOpen(false);
    }
  };

  return (
    <aside className={`w-full flex flex-col h-full bg-card ${className}`}>
      {/* Header with Table / Customer / Hold count */}
      <div className="p-3 border-b border-border space-y-2">
        <div className="flex items-center justify-between">
          <h2 className="font-bold text-sm text-foreground">Pesanan Kasir</h2>
          <div className="flex items-center gap-1.5">
            {holdBills.length > 0 && (
              <button
                onClick={() => setHoldModalOpen(true)}
                className="px-2 py-1 rounded-md bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300 text-xs font-semibold flex items-center gap-1 hover:bg-amber-200 transition-colors"
                title="Buka Nota Gantung"
              >
                <Bookmark className="w-3.5 h-3.5" />
                <span>{holdBills.length} Nota Gantung</span>
              </button>
            )}
            {items.length > 0 && (
              <button
                onClick={clearCart}
                className="p-1.5 rounded-md hover:bg-destructive/10 text-destructive text-xs transition-colors"
                title="Kosongkan Keranjang"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>

        {/* Quick Customer & Table Selectors */}
        <div className="grid grid-cols-2 gap-2">
          {/* Customer button */}
          <button
            onClick={() => setCustomerModalOpen(true)}
            className="flex items-center gap-2 p-2 rounded-lg bg-muted/60 hover:bg-muted text-xs text-left truncate transition-colors border border-border"
          >
            <User className="w-3.5 h-3.5 text-primary shrink-0" />
            <span className="truncate font-medium text-foreground">
              {selectedCustomer ? selectedCustomer.name : "Pilih Member"}
            </span>
          </button>

          {/* Table / Order Reference Input */}
          {mode === "FNB" ? (
            <div className="flex items-center gap-2 p-2 rounded-lg bg-muted/60 text-xs border border-border">
              <Utensils className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
              <input
                placeholder="No. Meja"
                value={tableNumber}
                onChange={(e) => setTableNumber(e.target.value)}
                className="w-full bg-transparent text-xs focus:outline-none text-foreground font-medium"
              />
            </div>
          ) : (
            <div className="flex items-center gap-2 p-2 rounded-lg bg-muted/60 text-xs border border-border">
              <FileText className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
              <input
                placeholder="Catatan Nota"
                value={orderNotes}
                onChange={(e) => setOrderNotes(e.target.value)}
                className="w-full bg-transparent text-xs focus:outline-none text-foreground"
              />
            </div>
          )}
        </div>
      </div>

      {/* Cart Items List */}
      <div className="flex-1 overflow-y-auto p-3 space-y-2.5">
        {items.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center p-6 text-muted-foreground">
            <Tag className="w-8 h-8 mb-2 opacity-40" />
            <p className="font-semibold text-xs">Keranjang masih kosong</p>
            <p className="text-[11px]">Pilih produk dari etalase kasir di sebelah kiri.</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.product.id}
              className="p-2.5 rounded-xl border border-border bg-background flex items-center justify-between gap-2 shadow-2xs"
            >
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-xs text-foreground truncate">{item.product.name}</p>
                <p className="text-[11px] text-muted-foreground">
                  {formatCurrency(item.appliedPrice)} × {item.quantity}
                </p>
              </div>

              {/* Quantity Controls */}
              <div className="flex items-center gap-1.5 shrink-0">
                <button
                  onClick={() => updateQuantity(item.product.id, item.quantity - 1)}
                  className="w-7 h-7 rounded-lg bg-muted hover:bg-muted/80 flex items-center justify-center text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                >
                  <Minus className="w-3.5 h-3.5" />
                </button>
                <span className="w-6 text-center text-xs font-bold text-foreground">{item.quantity}</span>
                <button
                  onClick={() => updateQuantity(item.product.id, item.quantity + 1)}
                  className="w-7 h-7 rounded-lg bg-muted hover:bg-muted/80 flex items-center justify-center text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                >
                  <Plus className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Cart Summary & Payment Bar */}
      <div className="p-3 border-t border-border bg-card/80 backdrop-blur-xs space-y-2.5">
        <div className="space-y-1.5 text-xs">
          <div className="flex justify-between text-muted-foreground">
            <span>Subtotal</span>
            <span>{formatCurrency(subtotal)}</span>
          </div>

          {/* Discount line */}
          <div className="flex justify-between items-center text-muted-foreground">
            <button
              onClick={() => setDiscountModalOpen(true)}
              className="text-primary hover:underline flex items-center gap-1 cursor-pointer"
            >
              <Percent className="w-3 h-3" />
              <span>Diskon {discountPercent > 0 ? `(${discountPercent}%)` : ""}</span>
            </button>
            <span className={discountPercent > 0 ? "text-red-500 font-semibold" : ""}>
              {discountPercent > 0 ? `-${formatCurrency(Math.round(subtotal * (discountPercent / 100)))}` : "Rp 0"}
            </span>
          </div>

          {/* Tax line */}
          {settings.taxEnabled && (
            <div className="flex justify-between text-muted-foreground">
              <span>PPN ({settings.taxPercentage}%)</span>
              <span>{formatCurrency(taxAmount)}</span>
            </div>
          )}

          <div className="pt-2 border-t border-border flex justify-between items-center">
            <span className="font-bold text-sm text-foreground">Total Tagihan</span>
            <span className="font-extrabold text-base text-primary">{formatCurrency(grandTotal)}</span>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="grid grid-cols-3 gap-2">
          <Button
            variant="outline"
            onClick={() => holdCurrentBill()}
            disabled={items.length === 0}
            className="col-span-1 text-xs h-10"
          >
            <Bookmark className="w-3.5 h-3.5 mr-1" />
            <span>Tahan</span>
          </Button>

          <Button
            onClick={onCheckout}
            disabled={items.length === 0}
            className="col-span-2 text-xs font-bold h-10 shadow-md bg-green-600 hover:bg-green-700 text-white"
          >
            <CreditCard className="w-4 h-4 mr-1.5" />
            <span>Bayar (F4)</span>
          </Button>
        </div>
      </div>

      {/* Customer Selection Modal */}
      <Dialog open={customerModalOpen} onOpenChange={setCustomerModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Pilih Pelanggan / Member CRM</DialogTitle>
            <DialogDescription>Pilih member untuk mengakumulasi poin loyalitas otomatis.</DialogDescription>
          </DialogHeader>
          <div className="max-h-60 overflow-y-auto space-y-2">
            <button
              onClick={() => {
                setSelectedCustomer(null);
                setCustomerModalOpen(false);
              }}
              className="w-full p-2.5 rounded-lg text-left border border-border hover:bg-muted text-xs font-medium"
            >
              Tanpa Pelanggan (Umum / Guest)
            </button>
            {customersList.map((cust) => (
              <button
                key={cust.id}
                onClick={() => {
                  setSelectedCustomer(cust);
                  setCustomerModalOpen(false);
                }}
                className={`w-full p-2.5 rounded-lg text-left border transition-colors flex items-center justify-between text-xs ${
                  selectedCustomer?.id === cust.id
                    ? "border-primary bg-primary/10 font-bold"
                    : "border-border hover:bg-muted"
                }`}
              >
                <div>
                  <p className="font-semibold text-foreground">{cust.name}</p>
                  <p className="text-[11px] text-muted-foreground">{cust.phone} • {cust.tier}</p>
                </div>
                <span className="text-[11px] font-bold text-primary">{cust.loyaltyPoints} Poin</span>
              </button>
            ))}
          </div>
        </DialogContent>
      </Dialog>

      {/* Hold Bills Modal */}
      <Dialog open={holdModalOpen} onOpenChange={setHoldModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Daftar Nota Gantung</DialogTitle>
            <DialogDescription>Pilih nota yang ingin dipanggil kembali ke kasir.</DialogDescription>
          </DialogHeader>
          <div className="max-h-64 overflow-y-auto space-y-2">
            {holdBills.map((bill) => (
              <div
                key={bill.id}
                className="p-3 rounded-lg border border-border bg-muted/40 flex items-center justify-between gap-2"
              >
                <div className="text-xs">
                  <p className="font-bold text-foreground">
                    {bill.tableNumber ? `Meja ${bill.tableNumber}` : bill.customerName || "Nota Tanpa Nama"}
                  </p>
                  <p className="text-[11px] text-muted-foreground">
                    {bill.items.length} item • Disimpan {bill.savedAt}
                  </p>
                </div>
                <div className="flex gap-1.5">
                  <Button
                    size="sm"
                    onClick={() => {
                      restoreHoldBill(bill.id);
                      setHoldModalOpen(false);
                    }}
                  >
                    Buka
                  </Button>
                  <Button
                    size="sm"
                    variant="destructive"
                    onClick={() => deleteHoldBill(bill.id)}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>

      {/* Discount Modal */}
      <Dialog open={discountModalOpen} onOpenChange={setDiscountModalOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Atur Diskon Nota</DialogTitle>
            <DialogDescription>
              Diskon di atas {settings.approvalDiscountThresholdPercent}% memerlukan persetujuan Supervisor.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <label className="text-xs font-semibold text-foreground">Persentase Diskon (%)</label>
              <Input
                type="number"
                placeholder="Contoh: 10"
                value={inputDiscount}
                onChange={(e) => setInputDiscount(e.target.value)}
                className="mt-1"
                min={0}
                max={100}
              />
            </div>
            <div className="grid grid-cols-4 gap-2">
              {[5, 10, 15, 20, 25, 30, 50].map((pct) => (
                <button
                  key={pct}
                  onClick={() => setInputDiscount(pct.toString())}
                  className="py-1.5 rounded-lg border border-border text-xs font-bold hover:bg-muted"
                >
                  {pct}%
                </button>
              ))}
            </div>
          </div>
          <DialogFooter className="mt-4">
            <Button variant="outline" onClick={() => setDiscountModalOpen(false)}>Batal</Button>
            <Button onClick={handleApplyDiscount}>Terapkan Diskon</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </aside>
  );
}

