      case "FNB": return <UtensilsCrossed className="w-3.5 h-3.5" />;
      case "RETAIL": return <ShoppingBag className="w-3.5 h-3.5" />;
      case "SALON": return <Scissors className="w-3.5 h-3.5" />;
