    organizationName: "OmniPOS Kopi & Bakery (Demo)",
    businessType: "FNB",
    hasCompletedOnboarding: true,
    createdAt: new Date().toISOString(),
    isActive: true,
  },
  {
    id: "user-kasir-demo",
    name: "Rina Kasir (Demo)",
    email: "kasir@nstok.id",
    password: "password123",
    role: "KASIR",
    organizationId: "org-demo-1",
    organizationName: "OmniPOS Kopi & Bakery (Demo)",
    businessType: "FNB",
    hasCompletedOnboarding: true,
    createdAt: new Date().toISOString(),
    isActive: true,
  },
  {
