    icon: "Globe",
    features: ["Sinkronisasi Online", "Cetak Resi", "Multi-Warehouse"],
  },
};

interface BusinessModeContextType {
  mode: BusinessArchetype;
  modeInfo: BusinessModeInfo;
  setMode: (mode: BusinessArchetype) => void;
}

const BusinessModeContext = createContext<BusinessModeContextType | null>(null);

export function BusinessModeProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const [mode, setModeState] = useState<BusinessArchetype>("FNB");

  const getStorageKey = () => {
    return user?.organizationId ? `nstok_${user.organizationId}_business_mode` : "nstok_business_mode_v3";
  };

  useEffect(() => {
    if (user?.businessType && ARCHETYPES[user.businessType as BusinessArchetype]) {
      setModeState(user.businessType as BusinessArchetype);
    } else {
      const key = getStorageKey();
      const saved = loadFromLocalStorage<BusinessArchetype>(key, "FNB");
      setModeState(saved);
    }
  }, [user?.businessType, user?.organizationId]);

  const setMode = (newMode: BusinessArchetype) => {
    setModeState(newMode);
    const key = getStorageKey();
    saveToLocalStorage(key, newMode);
  };

  return (
    <BusinessModeContext.Provider
      value={{
        mode,
        modeInfo: ARCHETYPES[mode] || ARCHETYPES.FNB,
        setMode,
      }}
    >
      {children}
    </BusinessModeContext.Provider>
  );
}

export function useBusinessMode() {
  const context = useContext(BusinessModeContext);
  if (!context) {
    throw new Error("useBusinessMode must be used within a BusinessModeProvider");
  }
  return context;
}

"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { Product, Customer } from "@/db/schema";
import { useWorkspaceSettings } from "./WorkspaceSettingsContext";
import { useAuth } from "./AuthContext";
import { loadFromLocalStorage, saveToLocalStorage } from "@/lib/dual-persistence";

export interface CartItem {
  product: Product;
  quantity: number;
  discountPercent?: number;
  itemNotes?: string;
  appliedPrice: number; // Effective price (wholesale or normal)
}

export interface HoldBill {
  id: string;
  tableNumber?: string;
  customerName?: string;
  customer?: Customer | null;
  items: CartItem[];
  savedAt: string;
  notes?: string;
}

interface CartContextType {
  items: CartItem[];
  selectedCustomer: Customer | null;
  tableNumber: string;
  orderNotes: string;
  discountPercent: number;
  discountAmount: number;
  subtotal: number;
  taxAmount: number;
  grandTotal: number;
  holdBills: HoldBill[];
  addToCart: (product: Product, qty?: number) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  setSelectedCustomer: (customer: Customer | null) => void;
  setTableNumber: (table: string) => void;
  setOrderNotes: (notes: string) => void;
  setDiscountPercent: (percent: number) => void;
  setDiscountAmount: (amount: number) => void;
  holdCurrentBill: (notes?: string) => boolean;
  restoreHoldBill: (billId: string) => void;
  deleteHoldBill: (billId: string) => void;
}

const CartContext = createContext<CartContextType | null>(null);

export function CartProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const { calculateTax, applyRounding } = useWorkspaceSettings();
  const [items, setItems] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [tableNumber, setTableNumber] = useState<string>("");
  const [orderNotes, setOrderNotes] = useState<string>("");
  const [discountPercent, setDiscountPercent] = useState<number>(0);
  const [discountAmount, setDiscountAmount] = useState<number>(0);
  const [holdBills, setHoldBills] = useState<HoldBill[]>([]);

  const orgId = user?.organizationId || "org-demo-1";
  const cartKey = `nstok_${orgId}_active_cart`;
  const holdKey = `nstok_${orgId}_hold_bills`;

  useEffect(() => {
    const savedCart = loadFromLocalStorage<CartItem[]>(cartKey, []);
    const savedHold = loadFromLocalStorage<HoldBill[]>(holdKey, []);
    setItems(savedCart);
    setHoldBills(savedHold);
  }, [orgId, cartKey, holdKey]);

  const saveCart = (newItems: CartItem[]) => {
    setItems(newItems);
    saveToLocalStorage(cartKey, newItems);
  };

  const addToCart = (product: Product, qty: number = 1) => {
    const sellingPrice = parseFloat(product.sellingPrice);
    const wholesalePrice = product.wholesalePrice ? parseFloat(product.wholesalePrice) : sellingPrice;
    const minWholesaleQty = product.minWholesaleQty || 999999;

    setItems((prev) => {
      const existingIndex = prev.findIndex((i) => i.product.id === product.id);
      let newItems: CartItem[];

      if (existingIndex >= 0) {
        newItems = [...prev];
        const newQty = newItems[existingIndex].quantity + qty;
        const effectivePrice = newQty >= minWholesaleQty ? wholesalePrice : sellingPrice;
        newItems[existingIndex] = {
          ...newItems[existingIndex],
          quantity: newQty,
          appliedPrice: effectivePrice,
        };
      } else {
        const effectivePrice = qty >= minWholesaleQty ? wholesalePrice : sellingPrice;
        newItems = [
          ...prev,
          {
            product,
            quantity: qty,
            appliedPrice: effectivePrice,
          },
        ];
      }

      saveToLocalStorage(cartKey, newItems);
      return newItems;
    });
  };

  const updateQuantity = (productId: string, quantity: number) => {
    if (quantity <= 0) {
      removeFromCart(productId);
      return;
    }

    setItems((prev) => {
      const newItems = prev.map((item) => {
        if (item.product.id === productId) {
          const sellingPrice = parseFloat(item.product.sellingPrice);
          const wholesalePrice = item.product.wholesalePrice ? parseFloat(item.product.wholesalePrice) : sellingPrice;
          const minWholesaleQty = item.product.minWholesaleQty || 999999;
          const effectivePrice = quantity >= minWholesaleQty ? wholesalePrice : sellingPrice;
          return { ...item, quantity, appliedPrice: effectivePrice };
        }
        return item;
      });
      saveToLocalStorage(cartKey, newItems);
      return newItems;
    });
  };

  const removeFromCart = (productId: string) => {
    setItems((prev) => {
      const newItems = prev.filter((i) => i.product.id !== productId);
      saveToLocalStorage(cartKey, newItems);
      return newItems;
    });
  };

  const clearCart = () => {
    setItems([]);
    setSelectedCustomer(null);
    setTableNumber("");
    setOrderNotes("");
    setDiscountPercent(0);
    setDiscountAmount(0);
    saveToLocalStorage(cartKey, []);
  };

  const subtotal = items.reduce((sum, item) => sum + item.appliedPrice * item.quantity, 0);
  const totalDiscount = discountAmount > 0 ? discountAmount : Math.round(subtotal * (discountPercent / 100));
  const subtotalAfterDiscount = Math.max(0, subtotal - totalDiscount);
  const taxAmount = calculateTax(subtotalAfterDiscount);
  const grandTotal = applyRounding(subtotalAfterDiscount + taxAmount);

  const holdCurrentBill = (notes?: string): boolean => {
    if (items.length === 0) return false;
    const newBill: HoldBill = {
      id: `bill-${Date.now()}`,
      tableNumber,
      customerName: selectedCustomer?.name,
      customer: selectedCustomer,
      items: [...items],
      savedAt: new Date().toLocaleTimeString("id-ID"),
      notes: notes || orderNotes,
    };
    const updated = [newBill, ...holdBills];
    setHoldBills(updated);
    saveToLocalStorage(holdKey, updated);
    clearCart();
    return true;
  };

  const restoreHoldBill = (billId: string) => {
    const bill = holdBills.find((b) => b.id === billId);
    if (!bill) return;
    setItems(bill.items);
    setSelectedCustomer(bill.customer || null);
    setTableNumber(bill.tableNumber || "");
    setOrderNotes(bill.notes || "");
    deleteHoldBill(billId);
    saveToLocalStorage(cartKey, bill.items);
  };

  const deleteHoldBill = (billId: string) => {
    const updated = holdBills.filter((b) => b.id !== billId);
    setHoldBills(updated);
    saveToLocalStorage(holdKey, updated);
  };

  return (
    <CartContext.Provider
      value={{
        items,
        selectedCustomer,
        tableNumber,
        orderNotes,
        discountPercent,
        discountAmount,
        subtotal,
        taxAmount,
        grandTotal,
        holdBills,
        addToCart,
        updateQuantity,
        removeFromCart,
        clearCart,
        setSelectedCustomer,
        setTableNumber,
        setOrderNotes,
        setDiscountPercent,
        setDiscountAmount,
        holdCurrentBill,
        restoreHoldBill,
        deleteHoldBill,
      }}
    >
      {children}
    </CartContext.Provider>
  );
}

export function useCart() {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error("useCart must be used within a CartProvider");
  }
  return context;
}

"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { loadFromLocalStorage, saveToLocalStorage } from "@/lib/dual-persistence";
import { useAuth } from "./AuthContext";

export interface ShiftData {
  id: string;
  cashierName: string;
  startingCash: number;
  expectedCash: number;
  actualCash?: number;
  discrepancy?: number;
  totalSales: number;
  totalTransactions: number;
  status: "OPEN" | "CLOSED";
  openedAt: string;
  closedAt?: string;
  notes?: string;
}

interface ShiftContextType {
  currentShift: ShiftData | null;
  isOpen: boolean;
  openShift: (startingCash: number, cashierName: string) => void;
  closeShift: (actualCash: number, notes?: string) => ShiftData;
  recordSale: (amount: number, isCash: boolean) => void;
}

const ShiftContext = createContext<ShiftContextType | null>(null);

export function ShiftProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const [currentShift, setCurrentShift] = useState<ShiftData | null>(null);

  const orgId = user?.organizationId || "org-demo-1";
  const shiftKey = `nstok_${orgId}_active_shift`;

  useEffect(() => {
    const saved = loadFromLocalStorage<ShiftData | null>(shiftKey, {
      id: `shift-init-${Date.now()}`,
      cashierName: user?.name || "Kasir Utama",
      startingCash: 200000,
      expectedCash: 200000,
      totalSales: 0,
      totalTransactions: 0,
      status: "OPEN",
      openedAt: new Date().toISOString(),
    });
    setCurrentShift(saved);
  }, [orgId, shiftKey, user?.name]);

  const openShift = (startingCash: number, cashierName: string) => {
    const newShift: ShiftData = {
      id: `shift-${Date.now()}`,
      cashierName,
      startingCash,
      expectedCash: startingCash,
      totalSales: 0,
      totalTransactions: 0,
      status: "OPEN",
      openedAt: new Date().toISOString(),
    };
    setCurrentShift(newShift);
    saveToLocalStorage(shiftKey, newShift);
  };

  const closeShift = (actualCash: number, notes?: string): ShiftData => {
    if (!currentShift) throw new Error("No active shift");
    const closed: ShiftData = {
      ...currentShift,
      actualCash,
      discrepancy: actualCash - currentShift.expectedCash,
      status: "CLOSED",
      closedAt: new Date().toISOString(),
      notes,
    };
    setCurrentShift(closed);
    saveToLocalStorage(shiftKey, closed);
    return closed;
  };

  const recordSale = (amount: number, isCash: boolean) => {
    if (!currentShift || currentShift.status !== "OPEN") return;
    setCurrentShift((prev) => {
      if (!prev) return null;
      const updated: ShiftData = {
        ...prev,
        totalSales: prev.totalSales + amount,
        totalTransactions: prev.totalTransactions + 1,
        expectedCash: isCash ? prev.expectedCash + amount : prev.expectedCash,
      };
      saveToLocalStorage(shiftKey, updated);
      return updated;
    });
  };

  return (
    <ShiftContext.Provider
      value={{
        currentShift,
        isOpen: currentShift?.status === "OPEN",
        openShift,
        closeShift,
        recordSale,
      }}
    >
      {children}
    </ShiftContext.Provider>
  );
}

export function useShift() {
  const context = useContext(ShiftContext);
  if (!context) {
    throw new Error("useShift must be used within a ShiftProvider");
  }
  return context;
}

